from pathlib import Path
import json
root=Path('docs/design/mobile-pdf-curation-task-v1');root.mkdir(exist_ok=True);assert not (root/'index.html').exists()
base=Path('docs/design/mobile-pdf-annotation-list-v4/index.html').read_text(encoding='utf-8').split('/* annotation-list */')[0]
css='''
/* reading-note-task */
.pdf-reading-note-task{--note-error:#a13e32;position:absolute;inset:0;z-index:18;display:flex;flex-direction:column;overflow:hidden;background:var(--bg);color:var(--ink)}
.reading-note-surface{display:flex;flex:1;flex-direction:column;min-height:0}.reading-note-header{display:flex;align-items:center;gap:8px;min-height:64px;padding:7.5px 8px;border-bottom:1px solid var(--line);flex:none}.reading-note-header h1{flex:1;min-width:0;margin:0;font-size:1.25rem;line-height:1.5;letter-spacing:normal;font-weight:700;overflow-wrap:anywhere}.reading-note-icon{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;padding:0;border:0;background:transparent;color:var(--muted)}
.reading-note-context{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;color:var(--muted);font-size:.8125rem;line-height:1.5384615385;flex:none}.reading-note-context p{margin:0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.reading-note-context>span{flex:none}
.reading-note-body{flex:1;min-height:0;padding:16px;overflow:auto;overscroll-behavior:contain}.reading-note-search{display:flex;align-items:stretch;gap:8px}.reading-note-query{flex:1;position:relative;min-width:0}.reading-note-query>svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}.reading-note-query input{display:block;width:100%;min-width:0;min-height:48px;padding:10px 40px;font:inherit;font-size:1rem;line-height:1.5;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:10px;appearance:none}.reading-note-query input::-webkit-search-cancel-button{display:none}.reading-note-query input::placeholder{color:var(--muted);opacity:1}.reading-note-query-clear{position:absolute;right:0;top:0;width:40px;height:100%;border:0;background:transparent;color:var(--muted)}.reading-note-filter{display:grid;place-items:center;flex:0 0 48px;width:48px;min-height:48px;padding:0;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--muted)}.reading-note-filter.is-active{background:var(--primary-soft);color:var(--primary);border-color:var(--primary)}
.reading-note-count{display:flex;flex-direction:column;gap:4px;margin:14px 0 10px;font-size:.875rem;line-height:1.5;color:var(--muted)}.reading-note-count strong{color:var(--ink);font-weight:600}.reading-note-cards{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}.reading-note-card{margin:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--surface)}.reading-note-card.is-selected{border-color:var(--primary);background:var(--primary-soft)}.reading-note-choice{display:flex;align-items:center;gap:14px;width:100%;min-height:96px;padding:12px 14px;cursor:pointer}.reading-note-choice>span{flex:1;min-width:0}.reading-note-choice input{flex:none;width:22px;height:22px;margin:0;accent-color:var(--primary)}.reading-note-meta{display:flex;align-items:center;gap:8px;font-size:.8125rem;line-height:1.5384615385;color:var(--muted)}.reading-note-choice strong{display:block;margin-top:6px;font-size:1rem;line-height:1.5;font-weight:650;overflow-wrap:anywhere}.reading-note-secondary{display:block;margin-top:4px;font-size:.875rem;line-height:1.5;color:var(--muted);overflow-wrap:anywhere}.reading-note-swatch{display:inline-block;flex:none;width:16px;height:16px;border-radius:4px}.color-yellow{background:#ffe16a}.color-green{background:#88bc7c}.color-pink{background:#ed9cb5}.color-blue{background:#88b9ed}
.reading-note-footer{display:flex;gap:8px;flex:none;padding:12px 16px calc(12px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:var(--bg);max-height:45dvh;overflow:auto}.reading-note-footer>.button{flex:1;min-width:0;min-height:48px;padding:11px 10px;border-radius:10px;font-size:.875rem;line-height:1.7142857143;font-weight:400}
.reading-note-filters fieldset{border:0;padding:0;margin:0}.reading-note-filters legend{font-size:1rem;font-weight:650;line-height:1.5;margin-bottom:12px;padding:0}.reading-note-colors{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--surface)}.reading-note-color,.reading-note-switch{display:flex;align-items:center;gap:12px;min-height:56px;padding:12px 14px;cursor:pointer;font-size:1rem;line-height:1.5}.reading-note-color+.reading-note-color{border-top:1px solid var(--line)}.reading-note-color>span,.reading-note-switch>span{flex:1;min-width:0}.reading-note-color input,.reading-note-switch input{flex:none;width:20px;height:20px;margin:0;accent-color:var(--primary)}.reading-note-switch{margin-top:20px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.reading-note-switch small{display:block;margin-top:4px;font-size:.875rem;line-height:1.5;color:var(--muted)}
.reading-note-preview>h2{margin:0 0 24px;font-size:1.125rem;line-height:1.5;font-weight:650}.reading-note-preview section+section{border-top:1px solid var(--line);margin-top:24px;padding-top:24px}.reading-note-preview h3{margin:0 0 12px;font-size:1rem;line-height:1.5;font-weight:650}.reading-note-preview blockquote{margin:0;border-left:3px solid var(--primary-soft);padding-left:12px;font-size:1rem;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}.reading-note-preview p{margin:12px 0 0;font-size:1rem;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}.reading-note-preview small{display:block;margin-top:10px;color:var(--muted);font-size:.8125rem;line-height:1.5}
.reading-note-empty,.reading-note-success{text-align:center;padding:40px 12px;color:var(--muted)}.reading-note-empty>svg,.reading-note-success>svg{color:var(--primary)}.reading-note-empty h2,.reading-note-success h2{margin:16px 0;font-size:1.125rem;line-height:1.5;color:var(--ink)}.reading-note-success-card{margin-top:24px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--surface);text-align:left}.reading-note-success-card strong{display:block;font-size:1rem;line-height:1.5;overflow-wrap:anywhere}.reading-note-success-card span{display:block;margin-top:6px;font-size:.875rem;line-height:1.5}.reading-note-success details{text-align:left;font-size:.875rem;line-height:1.6;overflow-wrap:anywhere}.reading-note-success summary{padding:14px 0;min-height:48px;cursor:pointer}.reading-note-error{color:var(--note-error);font-size:.875rem;line-height:1.6;overflow-wrap:anywhere;margin:0 0 16px}
.reading-note-layer{position:absolute;z-index:20;inset:0;display:flex;align-items:flex-end;background:#14261d66}.reading-note-dialog{display:flex;flex-direction:column;width:100%;max-height:calc(100% - 16px);min-height:0;background:var(--bg);border:1px solid var(--line);border-radius:16px 16px 0 0;overflow:hidden}.reading-note-dialog header{display:flex;align-items:center;gap:8px;min-height:64px;padding:7.5px 8px 7.5px 16px;border-bottom:1px solid var(--line);flex:none}.reading-note-dialog h2{flex:1;min-width:0;margin:0;font-size:1.25rem;line-height:1.5;font-weight:700;overflow-wrap:anywhere}.reading-note-dialog-body{padding:4px 16px calc(12px + env(safe-area-inset-bottom));overflow:auto;overscroll-behavior:contain;min-height:0}.reading-note-action{display:flex;align-items:center;gap:12px;width:100%;min-height:56px;padding:12px 4px;border:0;background:transparent;color:var(--ink);font:inherit;font-size:1rem;line-height:1.5;text-align:left;overflow-wrap:anywhere}.reading-note-action+.reading-note-action{border-top:1px solid var(--line)}.reading-note-action svg{flex:none}.reading-note-action>span{flex:1}
.reading-note-resume{display:flex;align-items:center;gap:12px;width:100%;min-height:64px;margin:0 0 16px;padding:12px;border:1px solid var(--primary);border-radius:10px;background:var(--primary-soft);color:var(--ink);text-align:left}.reading-note-resume>span{flex:1;min-width:0}.reading-note-resume strong,.reading-note-resume small{display:block;font-size:.875rem;line-height:1.6}.reading-note-resume small{font-weight:400;color:var(--muted)}
@media(max-width:340px){.reading-note-context{flex-wrap:wrap;gap:4px 12px}.reading-note-context p{flex-basis:100%}.reading-note-footer{flex-direction:column}.reading-note-footer>.button{flex:none}.reading-note-dialog h2{font-size:1.125rem}}
@media(max-height:400px){.reading-note-header{min-height:49px;padding:0 8px}.reading-note-header h1{font-size:1rem}.reading-note-context{display:none}.reading-note-body{padding:12px}.reading-note-footer{flex-direction:row;padding:8px 12px}.reading-note-footer>.button{flex:1;padding:8px 6px;font-size:.75rem;line-height:1.5}.reading-note-dialog header{min-height:49px;padding:0 8px 0 12px}.reading-note-dialog h2{font-size:1rem}}
'''
# Use the same established Lucide paths as the frozen annotation reference.
old=Path('docs/design/mobile-pdf-annotation-list-v4/index.html').read_text(encoding='utf-8')
icons=json.JSONDecoder().raw_decode(old.split('icons=',1)[1])[0]
icons['checkCircle']='<circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/>'
script=r'''
const screen=new URLSearchParams(location.search).get('screen')||'select',icons=ICONS;const icon=(name,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const colors={yellow:'黄色',green:'绿色',pink:'粉色',blue:'蓝色'},all=[{page:1,kind:'高亮',color:'green',comment:'为重要的想法留出空间。',quote:'Make room for ideas'},{page:1,kind:'高亮',color:'yellow',comment:'记住上次读到的位置。',quote:'Keep your place'},{page:3,kind:'评论',color:'blue',comment:'下次从这里继续。',quote:''}],filters=['filters','filters-edited'].includes(screen),review=['preview','error'].includes(screen),saved=screen==='saved',empty=screen==='empty',missing=screen==='no-match',filtered=screen==='filtered',selected=!['select','empty','no-match'].includes(screen),items=empty||missing?[]:filtered?[all[0]]:all,query=missing?'不存在的想法':filtered?'ideas':'',count=selected?2:0;
let body='';if(filters)body=`<div class="reading-note-filters"><fieldset><legend>标记颜色</legend><div class="reading-note-colors">${Object.entries({all:'全部颜色',...colors}).map(([c,t])=>`<label class="reading-note-color">${c==='all'?'':`<i class="reading-note-swatch color-${c}"></i>`}<span>${t}</span><input type="radio" name="note-color" ${c===(screen==='filters-edited'?'green':'all')?'checked':''}></label>`).join('')}</div></fieldset><label class="reading-note-switch"><span>仅当前页<small>第 1 页</small></span><input type="checkbox" ${screen==='filters-edited'?'checked':''}></label><label class="reading-note-switch"><span>仅看已选摘录<small>已选 2 条</small></span><input type="checkbox"></label></div>`;
else if(review)body=`${screen==='error'?'<p class="reading-note-error" role="alert">笔记尚未确认保存：本机空间不足。预览和选择仍保留，请释放空间后重试。</p>':''}<article class="reading-note-preview"><h2>阅读导航 · 阅读笔记</h2>${[all[0],all[2]].map(a=>`<section><h3>第 ${a.page} 页 · ${a.kind}</h3>${a.quote?`<blockquote>${a.quote}</blockquote>`:''}<p>${a.comment}</p><small>原文第 ${a.page} 页</small></section>`).join('')}</article>`;
else if(saved)body=`<div class="reading-note-success">${icon('checkCircle',44)}<h2>阅读笔记已保存</h2><div class="reading-note-success-card"><strong>阅读导航 · 阅读笔记</strong><span>Markdown · 手机资料库</span></div><details><summary>文件名称</summary><p>阅读导航-阅读笔记-唯一编号.md</p></details></div>`;
else body=`<div class="reading-note-search"><div class="reading-note-query">${icon('search',20)}<input type="search" value="${query}" placeholder="查找摘录或想法">${query?`<button class="reading-note-query-clear">${icon('close',18)}</button>`:''}</div><button class="reading-note-filter ${filtered?'is-active':''}">${icon('filter')}</button></div><p class="reading-note-count"><strong>已选 ${count} 条 · 找到 ${items.length} 条</strong>${filtered?'<span>其中 1 条不在当前范围</span>':''}</p>${items.length?`<ol class="reading-note-cards">${items.map(a=>{const check=selected&&a.color!=='yellow';return `<li class="reading-note-card ${check?'is-selected':''}"><label class="reading-note-choice"><span><span class="reading-note-meta"><i class="reading-note-swatch color-${a.color}"></i><span>第 ${a.page} 页 · ${a.kind}</span></span><strong>${a.comment||a.quote}</strong>${a.comment&&a.quote?`<span class="reading-note-secondary">${a.quote}</span>`:''}</span><input type="checkbox" ${check?'checked':''}></label></li>`}).join('')}</ol>`:`<div class="reading-note-empty">${icon(empty?'comment':'search',38)}<h2>${empty?'还没有批注':'没有匹配的摘录'}</h2>${missing?'<button class="button">清空搜索与筛选</button>':''}</div>`}`;
const footer=filters?'<button class="button">重置</button><button class="button primary-button">应用筛选</button>':review?'<button class="button">返回选择</button><button class="button primary-button">保存阅读笔记</button>':saved?'<button class="button">继续选择</button><button class="button primary-button">打开阅读笔记</button>':`<button class="button primary-button" ${count?'':'disabled'}>预览笔记 · ${count} 条</button>`;
const modal=screen==='actions'?`<div class="reading-note-layer"><section class="reading-note-dialog"><header><h2>选择操作</h2><button class="reading-note-icon">${icon('close')}</button></header><div class="reading-note-dialog-body"><button class="reading-note-action">${icon('check',20)}<span>选择当前结果 · 3 条</span></button><button class="reading-note-action">${icon('filter',20)}<span>仅看已选</span></button><button class="reading-note-action">${icon('trash',20)}<span>清空已选</span></button><button class="reading-note-action">${icon('refresh',20)}<span>重新读取批注</span></button></div></section></div>`:'';
document.querySelector('.phone').innerHTML=`<section class="pdf-reading-note-task"><div class="reading-note-surface"><header class="reading-note-header"><button class="reading-note-icon">${icon('back')}</button><h1>${filters?'筛选摘录':review?'预览笔记':saved?'已保存':'选择摘录'}</h1>${!filters&&!review&&!saved?`<button class="reading-note-icon">${icon('more')}</button>`:''}<button class="mobile-help-trigger">${icon('help',20)}</button></header><div class="reading-note-context"><p>阅读导航.pdf</p><span>${review||saved?'2 条 · 独立笔记':'当前第 1 页'}</span></div><div class="reading-note-body">${body}</div><footer class="reading-note-footer">${footer}</footer></div>${modal}</section>`;
'''.replace('ICONS',json.dumps(icons,ensure_ascii=False))
(root/'index.html').write_text(base+css+'</style><div class="phone"></div><script>'+script+'</script></html>',encoding='utf-8',newline='\n')
